// Time Complexity: O(N), Space Complexity: O(1)
pair<int, int> findMax(const vector<int>& arr) {
    if (arr.empty()) return {-1, -1};
    int maxVal = arr[0];
    int maxIdx = 0;
    for (size_t i = 1; i < arr.size(); ++i) {
        if (arr[i] > maxVal) {
            maxVal = arr[i];
            maxIdx = i;
        }
    }
    return {maxVal, maxIdx}; // Returns pair of {Value, Index}
}

