pair<int,int> maxMinDC(const vector<int>& a, int l, int r) {
    // returns {max, min}
    if (l == r) return {a[l], a[l]};               // 0 comparisons
    if (r == l + 1) {                               // 1 comparison
        if (a[l] > a[r]) return {a[l], a[r]};
        else return {a[r], a[l]};
    }
    int mid = l + (r - l) / 2;
    auto left  = maxMinDC(a, l, mid);
    auto right = maxMinDC(a, mid+1, r);
    int mx = (left.first > right.first) ? left.first : right.first; // compare maxes
    int mn = (left.second < right.second) ? left.second : right.second; // compare mins
    return {mx, mn};
}

int main(){
