#include <bits/stdc++.h>
using namespace std;

const int INF = 1e9;

struct Node {
    vector<vector<int>> mat; // reduced cost matrix
    int lowerBound;          // current lower bound
    int level;               // depth in tree (number of edges fixed)
    int pathCost;            // cost of edges already taken
    vector<pair<int,int>> path; // edges chosen so far
};

// Reduce matrix and return reduction cost
int reduceMatrix(vector<vector<int>>& m) {
    int n = m.size();
    int reduction = 0;
    // row reduction
    for (int i = 0; i < n; ++i) {
        int rowMin = INF;
        for (int j = 0; j < n; ++j) rowMin = min(rowMin, m[i][j]);
        if (rowMin == INF) continue;
        reduction += rowMin;
        for (int j = 0; j < n; ++j) if (m[i][j] != INF) m[i][j] -= rowMin;
    }
    // column reduction
    for (int j = 0; j < n; ++j) {
        int colMin = INF;
        for (int i = 0; i < n; ++i) colMin = min(colMin, m[i][j]);
        if (colMin == INF) continue;
        reduction += colMin;
        for (int i = 0; i < n; ++i) if (m[i][j] != INF) m[i][j] -= colMin;
    }
    return reduction;
}

// Create child node after choosing edge (i->j)
Node createChild(const Node& parent, int i, int j) {
    Node child = parent;
    child.level = parent.level + 1;
    child.path.push_back({i, j});
    child.pathCost += parent.mat[i][j];
    // set row i and column j to INF
    int n = child.mat.size();
    for (int k = 0; k < n; ++k) {
        child.mat[i][k] = INF; // cannot leave i again
        child.mat[k][j] = INF; // cannot enter j again
    }
    // forbid reverse edge to avoid 2‑cycle
    child.mat[j][i] = INF;
    // add reduction cost
    child.lowerBound = parent.lowerBound + parent.mat[i][j] + reduceMatrix(child.mat);
    return child;
}

int main() {
    // Example 4‑city distance matrix (0 on diagonal)
    vector<vector<int>> dist = {
        {INF, 10, 15, 20},
        {10, INF, 35, 25},
        {15, 35, INF, 30},
        {20, 25, 30, INF}
    };
    Node root; root.mat = dist; root.lowerBound = reduceMatrix(root.mat);
    root.level = 0; root.pathCost = 0;

    // Simple priority queue (min‑heap) on lowerBound
    auto cmp = [](const Node& a, const Node& b){ return a.lowerBound > b.lowerBound; };
    priority_queue<Node, vector<Node>, decltype(cmp)> pq(cmp);
    pq.push(root);
    int best = INF;
    vector<pair<int,int>> bestPath;

    while (!pq.empty()) {
        Node cur = pq.top(); pq.pop();
        if (cur.lowerBound >= best) continue; // prune
        if (cur.level == dist.size() - 1) { // last edge to complete tour
            // find remaining city
            int i = -1, j = -1;
            for (int a = 0; a < dist.size(); ++a)
                for (int b = 0; b < dist.size(); ++b)
                    if (cur.mat[a][b] != INF) { i = a; j = b; }
            int total = cur.pathCost + cur.mat[i][j];
            if (total < best) { best = total; bestPath = cur.path; bestPath.push_back({i,j}); }
            continue;
        }
        // branch on first zero element (i,j)
        int n = dist.size();
        bool branched = false;
        for (int i = 0; i < n && !branched; ++i) {
            for (int j = 0; j < n && !branched; ++j) {
                if (cur.mat[i][j] == 0) {
                    // include edge
                    Node inc = createChild(cur, i, j);
                    if (inc.lowerBound < best) pq.push(inc);
                    // exclude edge (set to INF and re‑reduce)
                    Node exc = cur;
                    exc.mat[i][j] = INF;
                    exc.lowerBound = cur.lowerBound + reduceMatrix(exc.mat);
                    if (exc.lowerBound < best) pq.push(exc);
                    branched = true;
                }
            }
        }
    }
    cout << "Optimal tour cost: " << best << "\n";
    cout << "Tour edges: ";
    for (auto &e : bestPath) cout << e.first << "->" << e.second << " ";
    cout << "\n";
    return 0;
}

