// Calculating the theoretical minimum number of comparisons (leaf depth)
// for comparison sorting using Stirling's approximation for log2(n!).
double minComparisonsLowerBound(int n) {
    if (n <= 1) return 0;
    // Stirling's approximation: log2(n!) approx n * log2(n) - 1.44n
    double n_log_n = n * log2(n);
    double stirling_sub = 1.442695 * n;
    return n_log_n - stirling_sub;
}

int main() {
    int n = 10;
    std::cout << "Min comparisons lower bound for " << n << " elements: " 
