struct Item {
    int weight, value;
};

int maxProfit = 0;
int n, W;
vector<Item> items;

void backtrack(int i, int curW, int curV) {
    if (curW <= W && curV > maxProfit) {
        maxProfit = curV; // Update global max profit
    }
    if (i == n || curW >= W) return;

    // Branch 1: Include item i
    if (curW + items[i].weight <= W) {
        backtrack(i + 1, curW + items[i].weight, curV + items[i].value);
    }
    // Branch 2: Exclude item i
    backtrack(i + 1, curW, curV);
}

