#include <iostream>
#include <vector>
#include <algorithm>
#include <queue>
using namespace std;

struct Item {
    int weight, value;
};

struct Node {
    int level, profit, weight;
    float bound;
};

struct CompareBound {
    bool operator()(const Node& a, const Node& b) {
        return a.bound < b.bound; // Max-heap based on bound
    };
};

bool compareItems(Item a, Item b) {
    double r1 = (double)a.value / a.weight;
    double r2 = (double)b.value / b.weight;
    return r1 > r2;
}

float bound(Node u, int n, int W, const vector<Item>& arr) {
    if (u.weight >= W) return 0;
    float profit_bound = u.profit;
    int j = u.level + 1;
    int totweight = u.weight;

    while ((j < n) && (totweight + arr[j].weight <= W)) {
        totweight += arr[j].weight;
        profit_bound += arr[j].value;
        j++;
    }
    if (j < n)
        profit_bound += (W - totweight) * ((float)arr[j].value / arr[j].weight);
    return profit_bound;
}

int knapsackBB(int W, vector<Item>& arr) {
    sort(arr.begin(), arr.end(), compareItems);
    int n = arr.size();
    priority_queue<Node, vector<Node>, CompareBound> PQ;
    Node u, v;

    u.level = -1; u.profit = u.weight = 0;
    u.bound = bound(u, n, W, arr);
    PQ.push(u);

    int maxProfit = 0;
    while (!PQ.empty()) {
        u = PQ.top();
        PQ.pop();

        if (u.bound > maxProfit) {
            v.level = u.level + 1;
            v.weight = u.weight + arr[v.level].weight;
            v.profit = u.profit + arr[v.level].value;

            if (v.weight <= W && v.profit > maxProfit)
                maxProfit = v.profit;

            v.bound = bound(v, n, W, arr);
            if (v.bound > maxProfit)
                PQ.push(v);

            v.weight = u.weight;
            v.profit = u.profit;
            v.bound = bound(v, n, W, arr);
            if (v.bound > maxProfit)
                PQ.push(v);
        }
    }
    return maxProfit;
}

int main() {
    int W = 50;
    vector<Item> arr = {{10, 60}, {20, 100}, {30, 120}};
    cout << "Optimal Profit (B&B): " << knapsackBB(W, arr) << endl;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

const int INF = 1e9;

int shortestPathKEdges(int n, vector<vector<pair<int, int>>>& adj, int src, int dest, int k) {
    // dp[i][u][v] stores shortest path from u to v using exactly i edges
    vector<vector<vector<int>>> dp(k + 1, vector<vector<int>>(n, vector<int>(n, INF)));

    for (int i = 0; i < n; ++i) dp[0][i][i] = 0;

    for (int edgeCount = 1; edgeCount <= k; ++edgeCount) {
        for (int u = 0; u < n; ++u) {
            for (int v = 0; v < n; ++v) {
                for (auto& edge : adj[u]) {
                    int w = edge.first;
                    int weight = edge.second;
                    if (dp[edgeCount - 1][w][v] != INF) {
                        dp[edgeCount][u][v] = min(dp[edgeCount][u][v], weight + dp[edgeCount - 1][w][v]);
                    }
                }
            }
        }
    }
    return dp[k][src][dest];
}

int main() {
    int n = 4;
    vector<vector<pair<int, int>>> adj(n);
    adj[0].push_back({1, 10});
    adj[1].push_back({2, 20});
    adj[0].push_back({2, 50});
    adj[2].push_back({3, 10});
    adj[1].push_back({3, 30});

    int k = 2;
    int ans = shortestPathKEdges(n, adj, 0, 3, k);
    if (ans >= INF) cout << "No path found\n";
    else cout << "Shortest path with " << k << " edges: " << ans << endl;
    return 0;
}
